    INSERT INTO public.words (topic_id, word, phonetic, meaning, example_sentence, lesson_name, lesson_order, word_order, created_at) VALUES
    (v_topic_id_10, 'fundamental', '/ˌfʌndəˈmentl/', '(adj) cơ bản, thiết yếu, có vai trò quan trọng', 'The stepwells were fundamental to the survival of people living in dry regions.', 'Test 1', 0, 1, NOW() + interval '1 seconds'),
    (v_topic_id_10, 'neglect', '/nɪˈɡlekt/', '(v/n) 1. sao nhãng, bỏ bê 2. sự bỏ bê', 'Many ancient buildings have suffered from years of neglect due to lack of maintenance.', 'Test 1', 0, 2, NOW() + interval '2 seconds'),
    (v_topic_id_10, 'restoration', '/ˌrestəˈreɪʃən/', '(n) sự khôi phục, phục hồi (đặc biệt là công trình)', 'The ancient structure remained in pristine condition after restoration.', 'Test 1', 0, 3, NOW() + interval '3 seconds'),
    (v_topic_id_10, 'inhabitant', '/ɪnˈhæbɪtənt/', '(n) cư dân, người sinh sống tại một nơi', 'The inhabitant plays an essential role in the overall system.', 'Test 1', 0, 4, NOW() + interval '4 seconds'),
    (v_topic_id_10, 'irrigation', '/ˌɪrɪˈɡeɪʃən/', '(n) sự tưới tiêu', 'The irrigation plays an essential role in the overall system.', 'Test 1', 0, 5, NOW() + interval '5 seconds'),
    (v_topic_id_10, 'architecture', '/ˈɑːkɪtektʃə(r)/', '(n) kiến trúc', 'The temple is famous for its intricate architecture and detailed carvings.', 'Test 1', 0, 6, NOW() + interval '6 seconds'),
    (v_topic_id_10, 'comprise', '/kəmˈpraɪz/', '(v) bao gồm, cấu thành', 'The parts are comprised by the whole.', 'Test 1', 0, 7, NOW() + interval '7 seconds'),
