    (v_topic_id_10, 'negotiate', '/nɪˈɡəʊʃieɪt/', '(v) 1. vượt qua (địa hình, trở ngại) 2. đàm phán', 'Researchers need to negotiate the key factors involved in this process.', 'Test 1', 0, 10, NOW() + interval '10 seconds'),
    (v_topic_id_10, 'elaborate', '/ɪˈlæbərət/', '(adj) cầu kỳ, tinh xảo, chi tiết', 'Could you elaborate on the plot for your novel for me?', 'Test 1', 0, 11, NOW() + interval '11 seconds'),
    (v_topic_id_10, 'shelter', '/ˈʃeltə(r)/', '(n/v) 1. nơi trú ẩn 2. che chở, bảo vệ', 'During the rainstorm, we sheltered under a tree.', 'Test 1', 0, 12, NOW() + interval '12 seconds'),
    (v_topic_id_10, 'relentless', '/rɪˈlentləs/', '(adj) không ngừng, khắc nghiệt', 'The study revealed a relentless aspect of modern development.', 'Test 1', 0, 13, NOW() + interval '13 seconds'),
