    (v_topic_id_10, 'embellish', '/ɪmˈbelɪʃ/', '(v) trang trí, làm đẹp thêm', 'The old book cover was embellished with golden letters', 'Test 1', 0, 15, NOW() + interval '15 seconds'),
    (v_topic_id_10, 'derelict', '/ˈderəlɪkt/', '(adj) bị bỏ hoang, xuống cấp', 'The study revealed a derelict aspect of modern development.', 'Test 1', 0, 16, NOW() + interval '16 seconds'),
    (v_topic_id_10, 'divert', '/daɪˈvɜːt/', '(v) chuyển hướng, điều chuyển', 'The workers diverted the stream away from the road.', 'Test 1', 0, 17, NOW() + interval '17 seconds'),
    (v_topic_id_10, 'undergo', '/ˌʌndəˈɡəʊ/', '(v) trải qua (một quá trình)', 'Many historical buildings need to undergo major restoration before they disappear.', 'Test 1', 0, 18, NOW() + interval '18 seconds'),
    (v_topic_id_10, 'pristine', '/ˈprɪstiːn/', '(adj) nguyên vẹn, trong tình trạng hoàn hảo', 'The ancient structure remained in pristine condition after restoration.', 'Test 1', 0, 19, NOW() + interval '19 seconds'),
    (v_topic_id_10, 'depict', '/dɪˈpɪkt/', '(v) miêu tả, khắc họa', 'The sculptures depict scenes from daily life in ancient India.', 'Test 1', 0, 20, NOW() + interval '20 seconds'),
