    (v_topic_id_10, 'vary in size and shape', '', 'đa dạng về kích thước và hình dạng', 'The project aims to vary in size and shape for sustainable development.', 'Test 1', 0, 26, NOW() + interval '26 seconds'),
    (v_topic_id_10, 'comprise a series of', '', 'bao gồm một chuỗi các...', 'The project aims to comprise a series of for sustainable development.', 'Test 1', 0, 27, NOW() + interval '27 seconds'),
    (v_topic_id_10, 'descend to the water source', '', 'đi xuống nguồn nước', 'The project aims to descend to the water source for sustainable development.', 'Test 1', 0, 28, NOW() + interval '28 seconds'),
    (v_topic_id_10, 'shelter visitors from', '', 'che chở ai khỏi...', 'The project aims to shelter visitors from for sustainable development.', 'Test 1', 0, 29, NOW() + interval '29 seconds'),
    (v_topic_id_10, 'fall into disuse', '', 'không còn được sử dụng', 'The project aims to fall into disuse for sustainable development.', 'Test 1', 0, 30, NOW() + interval '30 seconds'),
    (v_topic_id_10, 'undergo restoration', '', 'được trùng tu, phục hồi', 'The project aims to undergo restoration for sustainable development.', 'Test 1', 0, 31, NOW() + interval '31 seconds'),
    (v_topic_id_10, 'in pristine condition', '', 'trong tình trạng nguyên vẹn', 'The ancient structure remained in pristine condition after restoration.', 'Test 1', 0, 32, NOW() + interval '32 seconds'),
