    (v_topic_id_10, 'preserve cultural heritage', '', 'bảo tồn di sản văn hóa', 'The project aims to preserve cultural heritage for sustainable development.', 'Test 1', 0, 34, NOW() + interval '34 seconds'),
    (v_topic_id_10, 'serve as a reminder of', '', 'đóng vai trò như lời nhắc về', 'The project aims to serve as a reminder of for sustainable development.', 'Test 1', 0, 35, NOW() + interval '35 seconds'),
    (v_topic_id_10, 'architectural marvel', '', 'kỳ quan kiến trúc', 'The monument is considered an architectural marvel.', 'Test 1', 0, 36, NOW() + interval '36 seconds'),
    (v_topic_id_10, 'prospect', '/ˈprɒspekt/', '(n) triển vọng, viễn cảnh', 'The prospect plays an essential role in the overall system.', 'Test 1', 0, 37, NOW() + interval '37 seconds'),
    (v_topic_id_10, 'conceive', '/kənˈsiːv/', '(v) hình dung, tưởng tượng', 'It is difficult to conceive a future with strong economic growth without an efficient transport system.', 'Test 1', 0, 38, NOW() + interval '38 seconds'),
    (v_topic_id_10, 'vigorous', '/ˈvɪɡərəs/', '(adj) mạnh mẽ, phát triển mạnh', 'a vigorous shrub', 'Test 1', 0, 39, NOW() + interval '39 seconds'),
