    INSERT INTO public.words (topic_id, word, phonetic, meaning, example_sentence, lesson_name, lesson_order, word_order, created_at) VALUES
    (v_topic_id_10, 'revitalise', '/ˌriːˈvaɪtəlaɪz/', '(v) hồi sinh, phục hồi', 'Researchers need to revitalise the key factors involved in this process.', 'Test 1', 0, 51, NOW() + interval '51 seconds'),
