    (v_topic_id_11, 'replenish', '/rɪˈplenɪʃ/', '(v) làm đầy lại, bổ sung', 'It''s a popular product, and they have to replenish their stock of it frequently.', 'Test 1', 0, 87, NOW() + interval '1087 seconds'),
    (v_topic_id_11, 'aerosol', '/ˈeərəsɒl/', '(n) bình xịt / hạt khí dung (bụi lỏng/rắn trong không khí)', 'The aerosol plays an essential role in the overall system.', 'Test 1', 0, 88, NOW() + interval '1088 seconds'),
    (v_topic_id_11, 'stratosphere', '/ˈstrætəsfɪə(r)/', '(n) tầng bình lưu', 'The stratosphere plays an essential role in the overall system.', 'Test 1', 0, 89, NOW() + interval '1089 seconds'),
    (v_topic_id_11, 'dimming', '/ˈdɪmɪŋ/', '(n) sự làm mờ, sự suy giảm ánh sáng', 'The dimming plays an essential role in the overall system.', 'Test 1', 0, 90, NOW() + interval '1090 seconds'),
    (v_topic_id_11, 'scrutinise', '/ˈskruːtənaɪz/', '(v) xem xét, nghiên cứu kỹ lưỡng', 'Researchers need to scrutinise all potential environmental impacts before implementing large-scale schemes.', 'Test 1', 0, 91, NOW() + interval '1091 seconds'),
    (v_topic_id_11, 'reinforce', '/ˌriːɪnˈfɔːs/', '(v) củng cố, gia cố, tăng cường', 'He reinforced the handle with a metal rod and a bit of tape.', 'Test 1', 0, 92, NOW() + interval '1092 seconds'),
    (v_topic_id_11, 'shed', '/ʃed/', '(v) rụng (lá, lông), trút bỏ', 'During winter, deciduous trees like birches shed their leaves, allowing solar radiation to reflect off snow cover.', 'Test 1', 0, 93, NOW() + interval '1093 seconds'),
    (v_topic_id_11, 'substitute', '/ˈsʌbstɪtjuːt/', '(n/v) sự thay thế / thay thế', 'Experts agree that geo-engineering must be viewed as an emergency backup rather than a permanent substitute for emissions reduction.', 'Test 1', 0, 94, NOW() + interval '1094 seconds'),
    (v_topic_id_11, 'guarded', '/ˈɡɑːdɪd/', '(adj) thận trọng, giữ kẽ', 'The study revealed a guarded aspect of modern development.', 'Test 1', 0, 95, NOW() + interval '1095 seconds'),
    (v_topic_id_11, 'precipitation', '/prɪˌsɪpɪˈteɪʃn/', '(n) lượng mưa / hiện tượng giáng thủy', 'Deploying chemical aerosols in the atmosphere might cause unpredictable changes in regional precipitation levels.', 'Test 1', 0, 96, NOW() + interval '1096 seconds'),
    (v_topic_id_11, 'overshoot', '/ˌəʊvəˈʃuːt/', '(v) vượt quá mức quy định/mục tiêu', 'If cooling interventions are applied too aggressively, global temperatures might unintentionally overshoot target limits.', 'Test 1', 0, 97, NOW() + interval '1097 seconds'),
    (v_topic_id_11, 'scenario', '/səˈnɑːriəʊ/', '(n) kịch bản, viễn cảnh', 'Scientists remain cautious because stopping geo-engineering abruptly could create a dangerous warming scenario.', 'Test 1', 0, 98, NOW() + interval '1098 seconds'),
    (v_topic_id_11, 'induce', '/ɪnˈdjuːs/', '(v) gây ra, xúi giục', 'His meditation induced a compromise. Opium induces sleep.', 'Test 1', 0, 99, NOW() + interval '1099 seconds'),
    (v_topic_id_11, 'exclude', '/ɪkˈskluːd/', '(v) loại trừ, không bao gồm', 'to exclude young animals from the womb or from eggs', 'Test 1', 0, 100, NOW() + interval '1100 seconds');
    INSERT INTO public.words (topic_id, word, phonetic, meaning, example_sentence, lesson_name, lesson_order, word_order, created_at) VALUES
    (v_topic_id_11, 'intentional', '/ɪnˈtenʃənl/', '(adj) cố ý, có mục đích', 'The study revealed a intentional aspect of modern development.', 'Test 1', 0, 101, NOW() + interval '1101 seconds'),
    (v_topic_id_11, 'latitude', '/ˈlætɪtjuːd/', '(n) vĩ độ', 'Re-freezing polar ice caps is essential to maintaining low temperatures in regions located at a high latitude.', 'Test 1', 0, 102, NOW() + interval '1102 seconds'),
