    (v_topic_id_11, 'carbon emission', '', 'lượng khí thải cacbon', 'Cutting down our dependency on coal and oil requires drastically reducing global carbon emission.', 'Test 1', 0, 107, NOW() + interval '1107 seconds'),
    (v_topic_id_11, 'make major strides', '', 'có những bước tiến lớn', 'Several countries have managed to make major strides in developing green technologies over the past decade.', 'Test 1', 0, 108, NOW() + interval '1108 seconds'),
    (v_topic_id_11, 'large-scale manipulation', '', 'sự can thiệp / tác động trên quy mô lớn', 'The project aims to large-scale manipulation for sustainable development.', 'Test 1', 0, 109, NOW() + interval '1109 seconds'),
    (v_topic_id_11, 'backup generator', '', 'máy phát điện dự phòng', 'The project aims to backup generator for sustainable development.', 'Test 1', 0, 110, NOW() + interval '1110 seconds'),
    (v_topic_id_11, 'eye-catching idea', '', 'ý tưởng thu hút, gây chú ý', 'Installing a giant space mirror is widely considered the most eye-catching idea proposed by climate researchers.', 'Test 1', 0, 111, NOW() + interval '1111 seconds'),
    (v_topic_id_11, 'sunlight-refracting sunshade', '', 'tấm chắn nắng khúc xạ ánh sáng mặt trời', 'The project aims to sunlight-refracting sunshade for sustainable development.', 'Test 1', 0, 112, NOW() + interval '1112 seconds'),
    (v_topic_id_11, 'high latitude', '', 'vĩ độ cao (kề khu vực cực)', 'Re-freezing polar ice caps is essential to maintaining low temperatures in regions located at a high latitude.', 'Test 1', 0, 113, NOW() + interval '1113 seconds'),
    (v_topic_id_11, 'volcanic explosion', '', 'vụ nổ / phun trào núi lửa', 'Historical data shows that a major volcanic explosion can naturally inject thousands of tons of sulphur into the air. Compiled by CheeseNOTES 🧀', 'Test 1', 0, 114, NOW() + interval '1114 seconds'),
    (v_topic_id_11, 'short-term cooling', '', 'sự hạ nhiệt ngắn hạn', 'The project aims to short-term cooling for sustainable development.', 'Test 1', 0, 115, NOW() + interval '1115 seconds'),
    (v_topic_id_11, 'high-tension cable', '', 'cáp chịu lực / chịu kéo cao', 'The project aims to high-tension cable for sustainable development.', 'Test 1', 0, 116, NOW() + interval '1116 seconds'),
    (v_topic_id_11, 'permanent solution', '', 'giải pháp lâu dài / vĩnh viễn', 'The project aims to permanent solution for sustainable development.', 'Test 1', 0, 117, NOW() + interval '1117 seconds'),
    (v_topic_id_11, 'rainfall pattern', '', 'quy luật / mô hình lượng mưa', 'Atmospheric intervention could inadvertently alter the regional rainfall pattern and disrupt agricultural cycles.', 'Test 1', 0, 118, NOW() + interval '1118 seconds'),
