    INSERT INTO public.words (topic_id, word, phonetic, meaning, example_sentence, lesson_name, lesson_order, word_order, created_at) VALUES
    (v_topic_id_11, 'vessel', '/ˈvesl/', '(n) tàu lớn, thuyền lớn', 'The divers used powerful hydraulic jacks to overcome the immense suction force holding the vessel in the mud.', 'Test 2', 1, 1, NOW() + interval '1201 seconds'),
    (v_topic_id_11, 'undisputable', '/ˌʌndɪˈspjuː təbl/', '(adj) không thể tranh cãi, rõ ràng', 'The study revealed a undisputable aspect of modern development.', 'Test 2', 1, 2, NOW() + interval '1202 seconds'),
    (v_topic_id_11, 'starboard', '/ˈstɑːbəd/', '(n) mạn phải (của con tàu)', 'to starboard the helm', 'Test 2', 1, 3, NOW() + interval '1203 seconds'),
    (v_topic_id_11, 'port', '/pɔːt/', '(n) mạn trái (của con tàu)', 'Each eight has four ports and four starboards.', 'Test 2', 1, 4, NOW() + interval '1204 seconds'),
    (v_topic_id_11, 'degradation', '/ˌdeɡrəˈdeɪʃ n/', '(n) sự suy thoái, sự ăn mòn/phân hủy', 'The degradation plays an essential role in the overall system.', 'Test 2', 1, 5, NOW() + interval '1205 seconds'),
    (v_topic_id_11, 'intact', '/ɪnˈtækt/', '(adj) nguyên vẹn, không bị tổn hại', 'The archaeologists were amazed to find that half of the ship''s wooden structure had managed to remain intact under the clay layer.', 'Test 2', 1, 6, NOW() + interval '1206 seconds'),
    (v_topic_id_11, 'obstruction', '/əbˈstrʌkʃn/', '(n) chướng ngại vật, vật cản', 'The obstruction plays an essential role in the overall system.', 'Test 2', 1, 7, NOW() + interval '1207 seconds'),
    (v_topic_id_11, 'protrude', '/prəˈtruːd/', '(v) nhô ra, thò ra', 'Divers spotted a large piece of wooden timber that began to protrude slightly out of the seabed sand.', 'Test 2', 1, 8, NOW() + interval '1208 seconds'),
    (v_topic_id_11, 'obscurity', '/əbˈskjʊərət i/', '(n) sự lãng quên, trạng thái không ai biết đến', 'After sitting on the seabed for over a century, the historic warship gradually faded into obscurity.', 'Test 2', 1, 9, NOW() + interval '1209 seconds'),
    (v_topic_id_11, 'collaboration', '/kəˌlæbəˈre ɪʃn/', '(n) sự hợp tác', 'Collaboration can be a useful part of the creative process.', 'Test 2', 1, 10, NOW() + interval '1210 seconds'),
    (v_topic_id_11, 'excavation', '/ˌekskəˈveɪʃ n/', '(n) sự khai quật', 'The excavation plays an essential role in the overall system.', 'Test 2', 1, 11, NOW() + interval '1211 seconds'),
    (v_topic_id_11, 'climax', '/ˈklaɪmæks/', '(n) đỉnh điểm, điểm cao trào', 'The climax plays an essential role in the overall system.', 'Test 2', 1, 12, NOW() + interval '1212 seconds'),
    (v_topic_id_11, 'treasure trove', '/ˈtreʒə trəʊv/', '(n) kho báu / kho tàng giá trị', 'The discovery of thousands of perfectly preserved artifacts transformed the wreck into a true treasure trove. Compiled by CheeseNOTES 🧀', 'Test 2', 1, 13, NOW() + interval '1213 seconds'),
    (v_topic_id_11, 'salvage', '/ˈsælvɪdʒ/', '(v/n) cứu hộ (món đồ/con tàu bị chìm) / sự cứu hộ', 'The salvage team relied heavily on modern side-scan sonar to scan the seabed and pinpoint the location of the lost wreck.', 'Test 2', 1, 14, NOW() + interval '1214 seconds'),
    (v_topic_id_11, 'feasible', '/ˈfiːzəbl/', '(adj) khả thi, có thể thực hiện được', 'Experts spent years collecting data to determine whether it was technically feasible to raise the heavy timber hull.', 'Test 2', 1, 15, NOW() + interval '1215 seconds'),
    (v_topic_id_11, 'go-ahead', '/ˈɡəʊ əhed/', '(n) sự cho phép, sự đồng ý tiến hành', 'Authorities refused to give the go-ahead for the final retrieval operation until every risk factor was analyzed.', 'Test 2', 1, 16, NOW() + interval '1216 seconds'),
    (v_topic_id_11, 'hydraulic', '/haɪˈdrɔːlɪk/', '(adj) thủy lực (dùng áp lực chất lỏng)', 'The divers used powerful hydraulic jacks to overcome the immense suction force holding the vessel in the mud.', 'Test 2', 1, 17, NOW() + interval '1217 seconds'),
    (v_topic_id_11, 'cradle', '/ˈkreɪdl/', '(n) khung đỡ, giá đỡ', 'Before lifting the delicate hull out of the water, engineers custom-built a specially padded lifting cradle.', 'Test 2', 1, 18, NOW() + interval '1218 seconds'),
    (v_topic_id_11, 'cushion', '/ˈkʊʃn/', '(v/n) đệm lót, làm giảm chấn động', 'To protect the ship’s fragile structure during transfer, air bags were used to cushion the frame against shock.', 'Test 2', 1, 19, NOW() + interval '1219 seconds'),
    (v_topic_id_11, 'skeleton', '/ˈskelɪtn/', '(n) bộ khung, phần sườn', 'She dressed up as a skeleton for Halloween.', 'Test 2', 1, 20, NOW() + interval '1220 seconds'),
    (v_topic_id_11, 'undisciplined', '/ˌʌnˈdɪsəplɪ nd/', '(adj) thiếu kỷ luật', 'The study revealed a undisciplined aspect of modern development.', 'Test 2', 1, 21, NOW() + interval '1221 seconds'),
    (v_topic_id_11, 'erode', '/ɪˈrəʊd/', '(v) ăn mòn, xói mòn', 'Marine biologists warned that exposed sections of the hull would quickly erode due to salt water and organisms.', 'Test 2', 1, 22, NOW() + interval '1222 seconds'),
    (v_topic_id_11, 'intermittently', '/ˌɪntəˈmɪtə ntli/', '(adv) từng cơn, ngắt quãng, không liên tục', 'The phenomenon is intermittently observed in various natural environments.', 'Test 2', 1, 23, NOW() + interval '1223 seconds'),
    (v_topic_id_11, 'initiate', '/ɪˈnɪʃieɪt/', '(v) khởi xướng, bắt đầu', 'In 1965, a team of passionate divers decided to initiate a comprehensive search project along the coast.', 'Test 2', 1, 24, NOW() + interval '1224 seconds'),
    (v_topic_id_11, 'precise', '/prɪˈsaɪs/', '(adj) chính xác, tỉ mỉ', 'The complex salvage operation required precise coordination among divers, engineers, and maritime historians.', 'Test 2', 1, 25, NOW() + interval '1225 seconds'),
    (v_topic_id_11, 'sea battle', '', 'trận hải chiến', 'The project aims to sea battle for sustainable development.', 'Test 2', 1, 26, NOW() + interval '1226 seconds'),
    (v_topic_id_11, 'fighting career', '', 'sự nghiệp chiến đấu', 'Scientists attempted to fighting career during the investigation.', 'Test 2', 1, 27, NOW() + interval '1227 seconds'),
    (v_topic_id_11, 'mechanical degradation', '', 'sự suy giảm / hư hỏng do tác động cơ học', 'The project aims to mechanical degradation for sustainable development.', 'Test 2', 1, 28, NOW() + interval '1228 seconds'),
    (v_topic_id_11, 'remain intact', '', 'còn nguyên vẹn', 'The archaeologists were amazed to find that half of the ship''s wooden structure had managed to remain intact under the clay layer.', 'Test 2', 1, 29, NOW() + interval '1229 seconds'),
    (v_topic_id_11, 'fade into obscurity', '', 'chìm vào quên lãng', 'The project aims to fade into obscurity for sustainable development.', 'Test 2', 1, 30, NOW() + interval '1230 seconds'),
    (v_topic_id_11, 'search technique', '', 'kỹ thuật / phương pháp tìm kiếm', 'The project aims to search technique for sustainable development.', 'Test 2', 1, 31, NOW() + interval '1231 seconds'),
    (v_topic_id_11, 'side-scan sonar', '', 'ra-đa quét sườn (dùng sóng âm dưới nước)', 'The salvage team relied heavily on modern side-scan sonar to scan the seabed and pinpoint the location of the lost wreck.', 'Test 2', 1, 32, NOW() + interval '1232 seconds'),
    (v_topic_id_11, 'treasure trove', '', 'kho tàng di sản / bảo vật', 'The discovery of thousands of perfectly preserved artifacts transformed the wreck into a true treasure trove. Compiled by CheeseNOTES 🧀', 'Test 2', 1, 33, NOW() + interval '1233 seconds'),
    (v_topic_id_11, 'salvage operation', '', 'chiến dịch / hoạt động cứu hộ', 'The complex salvage operation required precise coordination among divers, engineers, and maritime historians.', 'Test 2', 1, 34, NOW() + interval '1234 seconds'),
    (v_topic_id_11, 'lifting frame', '', 'khung nâng', 'Scientists attempted to lifting frame during the investigation.', 'Test 2', 1, 35, NOW() + interval '1235 seconds'),
    (v_topic_id_11, 'hydraulic jack', '', 'kích thủy lực', 'The project aims to hydraulic jack for sustainable development.', 'Test 2', 1, 36, NOW() + interval '1236 seconds'),
    (v_topic_id_11, 'lifting cradle', '', 'giá đỡ nâng (dưới nước)', 'Before lifting the delicate hull out of the water, engineers custom-built a specially padded lifting cradle.', 'Test 2', 1, 37, NOW() + interval '1237 seconds'),
    (v_topic_id_11, 'survey drawing', '', 'bản vẽ khảo sát', 'Archaeologists created a detailed survey drawing of the wreck site before moving any major wooden components.', 'Test 2', 1, 38, NOW() + interval '1238 seconds'),
    (v_topic_id_11, 'timber framework', '', 'khung sườn gỗ', 'The project aims to timber framework for sustainable development.', 'Test 2', 1, 39, NOW() + interval '1239 seconds'),
    (v_topic_id_11, 'give the go-ahead', '', 'cấp phép / bật đèn xanh cho phép thực hiện', 'Authorities refused to give the go-ahead for the final retrieval operation until every risk factor was analyzed.', 'Test 2', 1, 40, NOW() + interval '1240 seconds'),
    (v_topic_id_11, 'isolated', '/ˈaɪsəleɪtɪd/', '(adj) biệt lập, cô lập', 'Modern environmentalists consider the tragic collapse of isolated societies to be a warning and a valuable lesson.', 'Test 2', 1, 41, NOW() + interval '1241 seconds'),
    (v_topic_id_11, 'ethnographer', '/eθˈnɒɡrəfə (r)/', '(n) nhà nhân chủng học / dân tộc học', 'The ethnographer plays an essential role in the overall system.', 'Test 2', 1, 42, NOW() + interval '1242 seconds'),
    (v_topic_id_11, 'extraterrestrial', '/ˌekstrətəˈr estriəl/', '(n/adj) sinh vật ngoài hành tinh / ngoài trái đất', 'The extraterrestrial plays an essential role in the overall system.', 'Test 2', 1, 43, NOW() + interval '1243 seconds'),
    (v_topic_id_11, 'sediment', '/ˈsedɪmənt/', '(n) trầm tích', 'The Nile delta is composed of sediment that was washed down and deposited at the mouth of the river.', 'Test 2', 1, 44, NOW() + interval '1244 seconds'),
    (v_topic_id_11, 'descendant', '/dɪˈsendənt /', '(n) con cháu, hậu duệ', 'The patriarch survived many descendants: five children, a dozen grandchildren, even a great grandchild.', 'Test 2', 1, 45, NOW() + interval '1245 seconds'),
    (v_topic_id_11, 'scenario', '/səˈnɑːriəʊ/', '(n) kịch bản, viễn cảnh', 'The scenario plays an essential role in the overall system.', 'Test 2', 1, 46, NOW() + interval '1246 seconds'),
    (v_topic_id_11, 'accelerate', '/əkˈseləreɪt /', '(v) tăng tốc, làm nhanh hơn', 'to accelerate the growth of a plant, the increase of wealth, etc.', 'Test 2', 1, 47, NOW() + interval '1247 seconds'),
    (v_topic_id_11, 'dominance', '/ˈdɒmɪnəns /', '(n) sự thống trị, thế ưu việt', 'Diamond claims that chieftains competed through massive moai construction as a public power display of their dominance.', 'Test 2', 1, 48, NOW() + interval '1248 seconds'),
    (v_topic_id_11, 'topple', '/ˈtɒpl/', '(v) quật ngã, làm đổ, lật đổ', 'Rival tribal factions began to topple the giant stone statues once civil conflicts erupted across Rapa Nui.', 'Test 2', 1, 49, NOW() + interval '1249 seconds'),
    (v_topic_id_11, 'catastrophe', '/kəˈtæstrəfi /', '(n) thảm họa, biến cố lớn', 'Jared Diamond argues that the islanders’ environmental misuse led directly to a major ecological catastrophe.', 'Test 2', 1, 50, NOW() + interval '1250 seconds');
    INSERT INTO public.words (topic_id, word, phonetic, meaning, example_sentence, lesson_name, lesson_order, word_order, created_at) VALUES
    (v_topic_id_11, 'infertile', '/ɪnˈfɜːtaɪl/', '(adj) cằn cỗi, không màu mỡ', 'Due to the severe lack of rain and windblown nutrients, the soil on the island was exceptionally infertile.', 'Test 2', 1, 51, NOW() + interval '1251 seconds'),
    (v_topic_id_11, 'pioneer', '/ˌpaɪəˈnɪə(r )/', '(n/v) người tiên phong / đi đầu', 'Certain politicians can be considered as pioneers of reform.', 'Test 2', 1, 52, NOW() + interval '1252 seconds'),
    (v_topic_id_11, 'sustainable', '/səˈsteɪnəbl /', '(adj) bền vững', 'The islanders developed sustainable agriculture methods by placing volcanic stones across fields to conserve moisture.', 'Test 2', 1, 53, NOW() + interval '1253 seconds'),
    (v_topic_id_11, 'contend', '/kənˈtend/', '(v) cho rằng, tranh luận rằng', 'Some scientists contend that European diseases, rather than internal war, caused the sudden collapse of the population.', 'Test 2', 1, 54, NOW() + interval '1254 seconds'),
    (v_topic_id_11, 'manoeuvre', '/məˈnuːvə(r )/', '(v/n) điều khiển, di chuyển khéo léo', 'Recent experiments showed that a handful of people could easily manoeuvre a huge moai replica using just three ropes.', 'Test 2', 1, 55, NOW() + interval '1255 seconds'),
    (v_topic_id_11, 'replica', '/ˈreplɪkə/', '(n) bản sao, mô hình như thật', 'Recent experiments showed that a handful of people could easily manoeuvre a huge moai replica using just three ropes.', 'Test 2', 1, 56, NOW() + interval '1256 seconds'),
    (v_topic_id_11, 'doom', '/duːm/', '(v/n) kết án, đẩy vào tình cảnh tồi tệ', 'They met an untimely doom when the mineshaft caved in.', 'Test 2', 1, 57, NOW() + interval '1257 seconds'),
    (v_topic_id_11, 'decimate', '/ˈdesɪmeɪt/', '(v) tàn phá, tiêu diệt hàng loạt', 'Historical evidence suggests that slave raids in the nineteenth century served to decimate the remaining native population.', 'Test 2', 1, 58, NOW() + interval '1258 seconds'),
    (v_topic_id_11, 'shrivel', '/ˈʃrɪvl/', '(v) co lại, suy giảm', 'Researchers need to shrivel the key factors involved in this process.', 'Test 2', 1, 59, NOW() + interval '1259 seconds'),
    (v_topic_id_11, 'ingenious', '/ɪnˈdʒiːniəs/', '(adj) khéo léo, thông minh, tài trí', 'Instead of being reckless destroyers, the Rapanui were likely ingenious stewards who adapted well to a harsh environment.', 'Test 2', 1, 60, NOW() + interval '1260 seconds'),
    (v_topic_id_11, 'steward', '/ˈstjuːəd/', '(n) người quản lý, người bảo vệ tài nguyên', 'a steward in a Methodist church', 'Test 2', 1, 61, NOW() + interval '1261 seconds'),
    (v_topic_id_11, 'abject', '/ˈæbdʒekt/', '(adj) khốn khổ, thảm hại, cực độ', 'The study revealed a abject aspect of modern development.', 'Test 2', 1, 62, NOW() + interval '1262 seconds'),
    (v_topic_id_11, 'reckless', '/ˈrekləs/', '(adj) liều lĩnh, thiếu suy nghĩ', 'Instead of being reckless destroyers, the Rapanui were likely ingenious stewards who adapted well to a harsh environment.', 'Test 2', 1, 63, NOW() + interval '1263 seconds'),
