    INSERT INTO public.words (topic_id, word, phonetic, meaning, example_sentence, lesson_name, lesson_order, word_order, created_at) VALUES
    (v_topic_id_12, 'desperate', '/ˈdespərət/', '(adj) tuyệt vọng, liều lĩnh', 'For nearly four decades, Bingham made a desperate attempt to prove his theory regarding the lost city of Vilcabamba.', 'Test 2', 1, 51, NOW() + interval '2251 seconds'),
    (v_topic_id_12, 'inaccurate', '/ɪnˈækjərət/', '(adj) không chính xác, sai lệch', 'Modern carbon-dating techniques revealed that Bingham’s original timeline for the site was entirely inaccurate.', 'Test 2', 1, 52, NOW() + interval '2252 seconds'),
    (v_topic_id_12, 'perplex', '/pəˈpleks/', '(v) làm bối rối, làm đau đầu suy nghĩ', 'The sudden disappearance of the city''s inhabitants prior to the invasion continues to perplex modern researchers.', 'Test 2', 1, 53, NOW() + interval '2253 seconds'),
    (v_topic_id_12, 'elite', '/eɪˈliːt/', '(n/adj) tầng lớp thượng lưu,', 'Members of the royal family and high-ranking Inca elite spent their winter months in warmer valley retreats.', 'Test 2', 1, 54, NOW() + interval '2254 seconds'),
    (v_topic_id_12, 'custom', '/ˈkʌstəm/', '(n) tập quán, phong tục', 'The Ancient Egyptian culture had many distinctive and interesting beliefs and customs.', 'Test 2', 1, 55, NOW() + interval '2255 seconds'),
    (v_topic_id_12, 'descendant', '/dɪˈsendənt/', '(n) con cháu, hậu duệ', 'The patriarch survived many descendants: five children, a dozen grandchildren, even a great grandchild.', 'Test 2', 1, 56, NOW() + interval '2256 seconds'),
    (v_topic_id_12, 'abandonment', '/əˈbændənmən t/', '(n) sự bỏ rơi, sự bỏ hoang', 'Since he left her, she''s suing him for divorce on grounds of abandonment.', 'Test 2', 1, 57, NOW() + interval '2257 seconds'),
    (v_topic_id_12, 'estate', '/ɪˈsteɪt/', '(n) điền trang, cơ ngơi', 'Recent archaeological evidence suggests Machu Picchu was originally designed as a peaceful country estate for the emperor.', 'Test 2', 1, 58, NOW() + interval '2258 seconds'),
    (v_topic_id_12, 'conquest', '/ˈkɒŋkwest/', '(n) sự xâm chiếm, sự chinh phục', 'Many historic cities across South America were permanently altered or destroyed during the era of the Spanish conquest.', 'Test 2', 1, 59, NOW() + interval '2259 seconds'),
    (v_topic_id_12, 'monumental', '/ˌmɒnjuˈmentl/', '(adj) vĩ đại, hoành tráng', 'Visitors to the sacred site are routinely awed by its extraordinary stonework and monumental architecture.', 'Test 2', 1, 60, NOW() + interval '2260 seconds'),
