    INSERT INTO public.words (topic_id, word, phonetic, meaning, example_sentence, lesson_name, lesson_order, word_order, created_at) VALUES
    (v_topic_id_15, 'comply', '/kəmˈplaɪ/', '(v) tuân theo, nghe theo', 'Following his father''s instruction, Henry Moore initially felt obliged to comply with the plan to become a schoolteacher.', 'Test 3', 2, 1, NOW() + interval '5401 seconds'),
    (v_topic_id_15, 'abandon', '/əˈbændən/', '(v) từ bỏ, bỏ dở', 'Due to a severe shortage of sculpting materials during World War II, Moore was forced to abandon stone carving and focus on drawing.', 'Test 3', 2, 2, NOW() + interval '5402 seconds'),
    (v_topic_id_15, 'recline', '/rɪˈklaɪn/', '(v) nằm ngửa, tựa lưng', 'Researchers need to recline the key factors involved in this process.', 'Test 3', 2, 3, NOW() + interval '5403 seconds'),
    (v_topic_id_15, 'recognition', '/ˌrekəɡˈnɪʃn/', '(n) sự công nhận, sự ghi nhận', 'The town of Harlow offered Moore a high-profile public recognition for a family sculpture, marking a major turning point in his career.', 'Test 3', 2, 4, NOW() + interval '5404 seconds'),
    (v_topic_id_15, 'emerging', '/ɪˈmɜːdʒɪŋ/', '(adj) mới nổi, đang phát triển', 'Unit One was established by young artists to persuade the public about the values of an emerging movement in modern art.', 'Test 3', 2, 5, NOW() + interval '5405 seconds'),
    (v_topic_id_15, 'notorious', '/nəʊˈtɔːriəs/', '(adj) tai tiếng, mang tiếng xấu', 'Press reviews of his early Leicester Galleries exhibition were extremely harsh, turning Moore into a notorious figure in British art.', 'Test 3', 2, 6, NOW() + interval '5406 seconds'),
    (v_topic_id_15, 'resignation', '/ˌrezɪɡˈneɪʃn/', '(n) sự từ chức, sự xin thôi việc', 'After his controversial exhibition at the Leicester Galleries, Moore faced severe backlash and a loud call for resignation from his position at the Royal College.', 'Test 3', 2, 7, NOW() + interval '5407 seconds'),
    (v_topic_id_15, 'inclination', '/ˌɪnklɪˈneɪʃn/', '(n) sự thiên hướng, ý thích', 'Throughout his early career, the sculptor showed little inclination to alter his style just to please traditional British art critics.', 'Test 3', 2, 8, NOW() + interval '5408 seconds'),
    (v_topic_id_15, 'distort', '/dɪˈstɔːt/', '(v) bóp méo, làm biến dạng', 'Inspired by Spanish painter Pablo Picasso, Moore began to distort the human body in a radical and unconventional manner.', 'Test 3', 2, 9, NOW() + interval '5409 seconds'),
    (v_topic_id_15, 'resemblance', '/rɪˈzembləns/', '(n) sự giống nhau, sự tương đồng', 'During the 1930s, Moore created abstract sketches that bore very little resemblance to the natural human form.', 'Test 3', 2, 10, NOW() + interval '5410 seconds'),
    (v_topic_id_15, 'commission', '/kəˈmɪʃn/', '(n) hợp đồng đặt hàng nghệ thuật', 'David received his commission after graduating from West Point.', 'Test 3', 2, 11, NOW() + interval '5411 seconds'),
