    (v_topic_id_15, 'revolutionary', '/ˌrevəˈluːʃənə ri/', '(adj) mang tính cách mạng, đột phá', 'revolutionary agitators', 'Test 3', 2, 13, NOW() + interval '5413 seconds'),
    (v_topic_id_15, 'threat / menace', '/ˈmenəs/', '(n) sự đe dọa, mối đe dọa', 'The threat / menace plays an essential role in the overall system.', 'Test 3', 2, 14, NOW() + interval '5414 seconds'),
    (v_topic_id_15, 'acclaim', '/əˈkleɪm/', '(n/v) sự hoan nghênh, sự tán thưởng', 'By the end of his career, Henry Moore had achieved widespread critical acclaim as one of the most prominent sculptors of the twentieth century.', 'Test 3', 2, 15, NOW() + interval '5415 seconds'),
    (v_topic_id_15, 'abstract', '/ˈæbstrækt/', '(adj) trừu tượng', 'During the 1930s, Moore created abstract sketches that bore very little resemblance to the natural human form.', 'Test 3', 2, 16, NOW() + interval '5416 seconds'),
    (v_topic_id_15, 'pierced', '/pɪəst/', '(adj) bị thủng, có lỗ rỗng', 'The study revealed a pierced aspect of modern development.', 'Test 3', 2, 17, NOW() + interval '5417 seconds'),
