    INSERT INTO public.words (topic_id, word, phonetic, meaning, example_sentence, lesson_name, lesson_order, word_order, created_at) VALUES
    (v_topic_id_16, 'Knowledge economy', '', 'Nền kinh tế tri thức', 'In a modern knowledge economy, high-level cognitive tasks rely increasingly on data analysis rather than physical labor.', 'Test 1', 0, 101, NOW() + interval '6101 seconds'),
    (v_topic_id_16, 'Human judgement', '', 'Sự đánh giá của con người', 'Complex tasks like interpreting medical scans or reading legal contracts used to require experienced human judgement.', 'Test 1', 0, 102, NOW() + interval '6102 seconds'),
    (v_topic_id_16, 'Peripheral participation', '', 'Sự tham gia học hỏi từ bên ngoài / thực tập', 'Junior employees traditionally learned complex skills by working alongside senior experts in a process called peripheral participation.', 'Test 1', 0, 103, NOW() + interval '6103 seconds'),
    (v_topic_id_16, 'Short-sighted view', '', 'Góc nhìn thiển cận', 'Relying blindly on automated decisions can lead to a short-sighted view that discourages human innovation.', 'Test 1', 0, 104, NOW() + interval '6104 seconds'),
    (v_topic_id_16, 'Working practice', '', 'Thói quen / Phương thức làm việc', 'When employees strictly follow algorithm instructions without question, it fundamentally changes their daily working practice.', 'Test 1', 0, 105, NOW() + interval '6105 seconds'),
    (v_topic_id_16, 'Full employment', '', 'Việc làm đầy đủ cho toàn dân', 'Bold political reforms are urgently needed to protect workers'' rights and guarantee long-term full employment.', 'Test 1', 0, 106, NOW() + interval '6106 seconds'),
    (v_topic_id_16, 'Economic democracy', '', 'Nền dân chủ kinh tế', 'Reforming financial capital laws can empower workers and foster greater economic democracy across society.', 'Test 1', 0, 107, NOW() + interval '6107 seconds'),
    (v_topic_id_16, 'Mass production', '', 'Sản xuất hàng loạt', 'The assembly line model introduced during the corporate revolution allowed factories to achieve unprecedented mass production.', 'Test 1', 0, 108, NOW() + interval '6108 seconds'),
    (v_topic_id_16, 'Industrial revolution', '', 'Cách mạng công nghiệp', 'Moving away from traditional agrarian lifestyles was one of the biggest transformations brought by the industrial revolution.', 'Test 1', 0, 109, NOW() + interval '6109 seconds'),
    (v_topic_id_16, 'Job security', '', 'Sự an toàn / ổn định công việc', 'Governments should proactively reprogram legal framework to enhance workforce protections and maintain job security.', 'Test 1', 0, 110, NOW() + interval '6110 seconds'),
    (v_topic_id_16, 'Social policy', '', 'Chính sách xã hội', 'Tackling structural unemployment caused by technological changes requires well-targeted state social policy.', 'Test 1', 0, 111, NOW() + interval '6111 seconds');
