    INSERT INTO public.words (topic_id, word, phonetic, meaning, example_sentence, lesson_name, lesson_order, word_order, created_at) VALUES
    (v_topic_id_16, 'Climate change', '', 'Biến đổi khí hậu', 'Rising global temperatures driven by climate change pose a massive challenge to ensuring future food security.', 'Test 3', 2, 101, NOW() + interval '6501 seconds'),
    (v_topic_id_16, 'Genetic switch', '', 'Công tắc di truyền / Cơ chế kích hoạt gen', 'Phytochromes act as a genetic switch that turns specific plant development genes on or off based on light and heat.', 'Test 3', 2, 102, NOW() + interval '6502 seconds'),
    (v_topic_id_16, 'Night-time heat', '', 'Nhiệt độ ban đêm', 'Plants measure night-time heat to read seasonal transitions and adjust their springtime development accordingly.', 'Test 3', 2, 103, NOW() + interval '6503 seconds'),
    (v_topic_id_16, 'Dark reversion', '', 'Sự đảo ngược trong bóng tối', 'During dark hours, the process of dark reversion determines how fast phytochrome molecules return to their inactive state.', 'Test 3', 2, 104, NOW() + interval '6504 seconds'),
    (v_topic_id_16, 'Thermal stress', '', 'Căng thẳng/Sốc nhiệt (do nhiệt độ quá cao)', 'High levels of thermal stress can significantly drop wheat and rice harvests by approximately 10% per degree of warming.', 'Test 3', 2, 105, NOW() + interval '6505 seconds'),
    (v_topic_id_16, 'Molecular scalpel', '', '"Dao mổ" phân tử (công cụ chỉnh sửa gen)', 'Modern gene-editing tools act like a molecular scalpel to precisely adjust plant DNA for better climate adaptation.', 'Test 3', 2, 106, NOW() + interval '6506 seconds'),
    (v_topic_id_16, 'Temperature sensitivity', '', 'Độ nhạy với nhiệt độ', 'Species with high temperature sensitivity can blossom months early if winter temperatures remain unusually warm.', 'Test 3', 2, 107, NOW() + interval '6507 seconds'),
    (v_topic_id_16, 'Seasonal change  Thay', '', 'đổi theo mùa', 'The project aims to Seasonal change Thay for sustainable development.', 'Test 3', 2, 108, NOW() + interval '6508 seconds'),
    (v_topic_id_16, 'Growth-suppressing state', '', 'Trạng thái ức chế tăng trưởng', 'When phytochromes remain active in cold weather, they keep the plant in a growth-suppressing state to prevent premature budding. Compiled by CheeseNOTES 🧀', 'Test 3', 2, 109, NOW() + interval '6509 seconds'),
    (v_topic_id_16, 'Plant biology', '', 'Sinh học thực vật', 'The new discovery in plant biology explains the molecular mechanism behind how plants respond to environmental heat.', 'Test 3', 2, 110, NOW() + interval '6510 seconds'),
    (v_topic_id_16, 'Plant genetics', '', 'Di truyền học thực vật', 'Breakthroughs in plant genetics enable researchers to identify and alter key temperature-sensing genes in crops.', 'Test 3', 2, 111, NOW() + interval '6511 seconds');
