    (v_topic_id_17, 'Confirmation bias', '', 'Thiên kiến xác nhận', 'The project aims to Confirmation bias for sustainable development.', 'Test 1', 0, 104, NOW() + interval '7104 seconds'),
    (v_topic_id_17, 'Personal recollections', '', 'Ký ức cá nhân', 'Years after regaining his throne, Charles II dictated his private memories and vivid personal recollections to Samuel Pepys.', 'Test 1', 0, 105, NOW() + interval '7105 seconds'),
