    INSERT INTO public.words (topic_id, word, phonetic, meaning, example_sentence, lesson_name, lesson_order, word_order, created_at) VALUES
    (v_topic_id_17, 'Trial and error', '', 'Phương pháp thử và sai', 'Breakthroughs in human history are rarely single events, but rather a result of a gradual process of trial and error.', 'Test 2', 1, 101, NOW() + interval '7301 seconds'),
