    (v_topic_id_17, 'Prime breeding season', '', 'Mùa sinh sản chính', 'Temporary protection was initially introduced in December because it was believed to be their prime breeding season. Compiled by CheeseNOTES 🧀', 'Test 3', 2, 31, NOW() + interval '7431 seconds'),
    (v_topic_id_17, 'Captive specimen', '', 'Cá thể bị nuôi nhốt', 'The very last known captive specimen died in captivity at Hobart Zoo in September 1936.', 'Test 3', 2, 32, NOW() + interval '7432 seconds'),
    (v_topic_id_17, 'Definitive evidence', '', 'Bằng chứng xác thực', 'Recent searching expeditions have failed to produce any definitive evidence that the species still roams the wilderness.', 'Test 3', 2, 33, NOW() + interval '7433 seconds'),
    (v_topic_id_17, 'Official protection', '', 'Sự bảo vệ chính thức', 'Tasmanian authorities delayed passing laws for official protection, granting immunity only right before the last wild thylacine died.', 'Test 3', 2, 34, NOW() + interval '7434 seconds'),
    (v_topic_id_17, 'European settler', '', 'Người định cư châu Âu', 'The arrival of the European settler introduced wild dogs and destroyed much of the native wildlife''s environment.', 'Test 3', 2, 35, NOW() + interval '7435 seconds'),
    (v_topic_id_17, 'Extinction process', '', 'Quá trình tuyệt chủng', 'The project aims to Extinction process for sustainable development.', 'Test 3', 2, 36, NOW() + interval '7436 seconds'),
    (v_topic_id_17, 'Natural environment', '', 'Môi trường tự nhiên', 'The project aims to Natural environment for sustainable development.', 'Test 3', 2, 37, NOW() + interval '7437 seconds'),
    (v_topic_id_17, 'monoculture', '/ˈmɒnəkʌltʃə(r) /', '(n) sự độc canh (trồng một loại cây)', 'The monoculture plays an essential role in the overall system.', 'Test 3', 2, 38, NOW() + interval '7438 seconds'),
    (v_topic_id_17, 'biodiversity', '/ˌbaɪəʊdaɪˈvɜː səti/', '(n) sự đa dạng sinh học', 'Environmentalists warn that replacing primary rainforests with oil palms poses a severe threat to global biodiversity.', 'Test 3', 2, 39, NOW() + interval '7439 seconds'),
    (v_topic_id_17, 'conservationist', '/ˌkɒnsəˈveɪʃən ɪst/', '(n) nhà bảo tồn thiên nhiên', 'The conservationist plays an essential role in the overall system.', 'Test 3', 2, 40, NOW() + interval '7440 seconds'),
    (v_topic_id_17, 'dwindling', '/ˈdwɪndlɪŋ/', '(adj) đang sụt giảm, thu nhỏ dần', 'The rapid destruction of ecosystems directly threatens the survival of many dwindling species in affected tropical forests.', 'Test 3', 2, 41, NOW() + interval '7441 seconds'),
    (v_topic_id_17, 'nuanced', '/ˈnjuːɑːnst/', '(adj) có nhiều sắc thái, tinh tế', 'Experts argue that a simple blanket ban ignores complex economic factors, advocating instead for a more nuanced perspective.', 'Test 3', 2, 42, NOW() + interval '7442 seconds'),
    (v_topic_id_17, 'boycott', '/ˈbɔɪkɒt/', '(v/n) tẩy chay, sự tẩy chay', 'Activists urged environmental groups and consumers worldwide to completely boycott products containing non-certified oil.', 'Test 3', 2, 43, NOW() + interval '7443 seconds'),
    (v_topic_id_17, 'contention', '/kənˈtenʃn/', '(n) sự tranh cãi, điểm bất đồng', 'Striking a fair decision between economic growth in poor regions and ecological preservation remains a major bone of contention.', 'Test 3', 2, 44, NOW() + interval '7444 seconds'),
    (v_topic_id_17, 'sequester', '/sɪˈkwestə(r)/', '(v) hấp thụ, lưu giữ', 'Oil palm crops are able to sequester substantial amounts of atmospheric carbon compared to certain annual crops.', 'Test 3', 2, 45, NOW() + interval '7445 seconds'),
    (v_topic_id_17, 'epiphytic', '/ˌepɪˈfɪtɪk/', '(adj) thuộc loài thực vật sống bám trên cây', 'The study revealed a epiphytic aspect of modern development.', 'Test 3', 2, 46, NOW() + interval '7446 seconds'),
    (v_topic_id_17, 'keystone species', '/ˈkiːstəʊn ˈspiːʃiːz/', '(n) loài chủ chốt trong hệ sinh thái', 'The bird’s nest fern plays a vital ecological role in maintaining forest biodiversity as a crucial keystone species.', 'Test 3', 2, 47, NOW() + interval '7447 seconds'),
    (v_topic_id_17, 'invertebrate', '/ɪnˈvɜːtɪbrət/', '(n/adj) động vật không xương sống', 'The invertebrate plays an essential role in the overall system.', 'Test 3', 2, 48, NOW() + interval '7448 seconds'),
    (v_topic_id_17, 'deforestation', '/ˌdiːˌfɒrɪˈsteɪʃn /', '(n) sự tàn phá rừng', 'The deforestation plays an essential role in the overall system.', 'Test 3', 2, 49, NOW() + interval '7449 seconds'),
    (v_topic_id_17, 'utilitarian', '/ˌjuːtɪlɪˈteəriən /', '(adj) thực dụng, vị lợi', 'Researchers emphasize the need to find a reasonable utilitarian balance that weighs human livelihoods against nature conservation.', 'Test 3', 2, 50, NOW() + interval '7450 seconds');
    INSERT INTO public.words (topic_id, word, phonetic, meaning, example_sentence, lesson_name, lesson_order, word_order, created_at) VALUES
    (v_topic_id_17, 'yield', '/jiːld/', '(n/v) sản lượng, năng suất', 'Compared to alternative vegetable crops, oil palm plantations generate an exceptionally high yield per hectare.', 'Test 3', 2, 51, NOW() + interval '7451 seconds'),
