    INSERT INTO public.words (topic_id, word, phonetic, meaning, example_sentence, lesson_name, lesson_order, word_order, created_at) VALUES
    (v_topic_id_17, 'conservation', '/ˌkɒnsəˈveɪʃn /', '(n) sự bảo tồn', 'Promoting bat conservation helps rural families build a more sustainable livelihood without relying on destructive farming techniques.', 'Test 4', 3, 1, NOW() + interval '7601 seconds'),
