    INSERT INTO public.words (topic_id, word, phonetic, meaning, example_sentence, lesson_name, lesson_order, word_order, created_at) VALUES
    (v_topic_id_18, 'erratic', '/ɪˈrætɪk/', '(adj) thất thường, không ổn định', 'Buyers of the early Model C reported that the cars were extremely erraticerratic and sometimes unexpectedly went in reverse.', 'Test 3', 2, 51, NOW() + interval '8451 seconds'),
    (v_topic_id_18, 'glitch', '/ɡlɪtʃ/', '(n) lỗi kỹ thuật nhỏ', 'They are still trying to work out all the glitches.', 'Test 3', 2, 52, NOW() + interval '8452 seconds'),
    (v_topic_id_18, 'viable', '/ˈvaɪəbl/', '(adj) khả thi, có thể phát triển', 'The study revealed a viable aspect of modern development.', 'Test 3', 2, 53, NOW() + interval '8453 seconds'),
    (v_topic_id_18, 'handling', '/ˈhændlɪŋ/', '(n) khả năng điều khiển', 'Despite its heavy weight, the Model E demonstrated excellent road handling once the boiler reached its full operating pressureoperating pressure.', 'Test 3', 2, 54, NOW() + interval '8454 seconds'),
