    (v_topic_id_18, 'Draw the attention of', '', 'Thu hút sự chú ý của', 'Due to its remarkable speed and silent engine, the Model B managed to draw the attention ofdraw the attention of auto trade magazines.', 'Test 3', 2, 65, NOW() + interval '8465 seconds'),
    (v_topic_id_18, 'Seek investment', '', 'Tìm kiếm vốn đầu tư', 'Abner Doble traveled all the way to Detroit in order to seek investmentseek investment for his new car manufacturing company.', 'Test 3', 2, 66, NOW() + interval '8466 seconds'),
    (v_topic_id_18, 'Eliminate the need for', '', 'Loại bỏ sự cần thiết của (không cần phải...)', 'The Doble brothers added a key-based ignition system to their vehicle to eliminate the need foreliminate the need for manually lighting the boiler.', 'Test 3', 2, 67, NOW() + interval '8467 seconds'),
    (v_topic_id_18, 'Operating pressure', '', 'Áp suất hoạt động', 'Despite its heavy weight, the Model E demonstrated excellent road handling once the boiler reached its full operating pressureoperating pressure.', 'Test 3', 2, 68, NOW() + interval '8468 seconds'),
