    (v_topic_id_19, 'charcoal', '/ˈtʃɑːkəʊl/', '(n) than củi', 'Replacing charcoal with coke drastically reduced expenses associated with smelting iron ore across major foundry networks.', 'Test 2', 1, 6, NOW() + interval '9206 seconds'),
    (v_topic_id_19, 'urbanisation', '/ˌɜːbənaɪˈzeɪʃ n/', '(n) sự đô thị hóa', 'Unprecedented migration into industrial cities caused dramatic problems linked to rapid urbanisation.', 'Test 2', 1, 7, NOW() + interval '9207 seconds'),
