    (v_topic_id_19, 'livelihood', '/ˈlaɪvlihʊd/', '(n) kế sinh nhai, phương kế sống', 'Artisans opposed new machinery because they feared unlearned workers would rob them of their traditional livelihood.', 'Test 2', 1, 9, NOW() + interval '9209 seconds'),
    (v_topic_id_19, 'apprentice', '/əˈprentɪs/', '(n) người học việc, tập sự', 'He was apprenticed to a local employer.', 'Test 2', 1, 10, NOW() + interval '9210 seconds'),
    (v_topic_id_19, 'resistance', '/rɪˈzɪstəns/', '(n) sự kháng cự, chống đối', 'the resistance of bacteria to certain antibiotics', 'Test 2', 1, 11, NOW() + interval '9211 seconds'),
